import { isPrimaryPointer } from "./utils/index.js";
export function extractEventInfo(event, pointType = "page") {
    return {
        point: {
            x: event[`${pointType}X`],
            y: event[`${pointType}Y`],
        },
    };
}
export function addPointerInfo(handler) {
    return (event) => isPrimaryPointer(event) && handler(event, extractEventInfo(event));
}
